insert into public.ingredients (id, canonical_name, aka, cas_number, e_number_ins_code, chemical_formula, category, origin, typical_uses, allergen_flags, plain_explanation, jurisdictions, risk_assessment_refs, usage_context, source, source_updated_at, last_full_review_at, everyday_allowlist, dataset_version)
select id, canonical_name, aka, cas_number, e_number_ins_code, chemical_formula, category, origin, typical_uses, allergen_flags, plain_explanation, jurisdictions, risk_assessment_refs, usage_context, source, source_updated_at, last_full_review_at, everyday_allowlist, dataset_version from incoming
on conflict (id) do update set
  canonical_name = excluded.canonical_name,
  aka = excluded.aka,
  cas_number = excluded.cas_number,
  e_number_ins_code = excluded.e_number_ins_code,
  chemical_formula = excluded.chemical_formula,
  category = excluded.category,
  origin = excluded.origin,
  typical_uses = excluded.typical_uses,
  allergen_flags = excluded.allergen_flags,
  plain_explanation = excluded.plain_explanation,
  jurisdictions = excluded.jurisdictions,
  risk_assessment_refs = excluded.risk_assessment_refs,
  usage_context = excluded.usage_context,
  source = excluded.source,
  source_updated_at = excluded.source_updated_at,
  last_full_review_at = excluded.last_full_review_at,
  everyday_allowlist = excluded.everyday_allowlist,
  dataset_version = excluded.dataset_version;

-- Names are rebuilt whole: they are derived data, and a partial update could
-- briefly let one name point at two ingredients.
delete from public.ingredient_names;
